当模式串数量多、嵌套匹配频繁时，内层 fail 链跳转成为性能瓶颈，需要拓扑排序优化。

五、效率优化：fail 树与拓扑排序
5.1 fail 树的核心性质
仅保留所有 fail 边，得到的图一定是一棵以根为根的树（fail 树）。


每个节点有且仅有一个 fail 指针；


fail 指针始终指向深度更浅的节点，不可能成环。


在 fail 树上，父节点是子节点的最长后缀状态。若文本串匹配到了子节点状态，则其所有祖先状态对应的后缀也被匹配到。
5.2 优化思路


匹配阶段：只在到达的状态上打计数标记，不跳 fail 链；


统计阶段：在 fail 树上按拓扑序（从叶子到根）将子节点的计数累加到父节点，一次性得到所有状态的匹配次数。


该优化将匹配复杂度降为严格 \(O\left(|T|\right)\)，总复杂度与匹配次数无关，是竞赛大数据的标准写法。
5.3 完整实现
int in[MAXN];   // fail树的入度
int val[MAXN];  // 状态被经过的次数
int ans[MAXN];  // 每个模式串的最终出现次数

void build() {
    queue<int> q;
    for (int i = 0; i < SIGMA; i++) {
        if (ch[0][i]) q.push(ch[0][i]);
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int i = 0; i < SIGMA; i++) {
            if (ch[u][i]) {
                fail[ch[u][i]] = ch[fail[u]][i];
                in[fail[ch[u][i]]]++;  // 统计fail树入度
                q.push(ch[u][i]);
            } else {
                ch[u][i] = ch[fail[u]][i];
            }
        }
    }
}

void query(string &t) {
    int u = 0;
    for (char ch : t) {
        int c = ch - 'a';
        u = ch[u][c];
        val[u]++;  // 只打标记，不跳fail
    }
}

void topo_sort() {
    queue<int> q;
    for (int i = 0; i <= tot; i++) {
        if (in[i] == 0) q.push(i);
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        ans[u] = val[u];
        int v = fail[u];
        val[v] += val[u];  // 子节点计数累加到父节点
        if (--in[v] == 0) q.push(v);
    }
}


六、完整模板
6.1 基础版：统计出现过的模式串总数
对应题目：洛谷 P3808 AC 自动机（简单版）
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e6 + 10;
const int SIGMA = 26;

int ch[MAXN][SIGMA];
int fail[MAXN];
int cnt[MAXN];
int tot;

void insert(string &s) {
    int u = 0;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) ch[u][v] = ++tot;
        u = ch[u][v];
    }
    cnt[u]++;
}

void build() {
    queue<int> q;
    for (int i = 0; i < SIGMA; i++)
        if (ch[0][i]) q.push(ch[0][i]);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int i = 0; i < SIGMA; i++) {
            if (ch[u][i]) {
                fail[ch[u][i]] = ch[fail[u]][i];
                q.push(ch[u][i]);
            } else ch[u][i] = ch[fail[u]][i];
        }
    }
}

int query(string &t) {
    int u = 0, res = 0;
    for (char c : t) {
        u = ch[u][c - 'a'];
        for (int j = u; j && cnt[j] != -1; j = fail[j]) {
            res += cnt[j];
            cnt[j] = -1;
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin >> n;
    for (int i = 1; i <= n; i++) {
        string s; cin >> s;
        insert(s);
    }
    build();
    string t; cin >> t;
    cout << query(t) << endl;
    return 0;
}

6.2 进阶版：每个模式串出现次数（拓扑优化）
对应题目：洛谷 P5357【模板】AC 自动机
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 2e6 + 10;
const int SIGMA = 26;

int ch[MAXN][SIGMA];
int fail[MAXN];
int id[MAXN];   // 该节点对应第几个模式串，0表示无
int in[MAXN];
int val[MAXN];
int res[MAXN];  // 第i个模式串的答案
int tot, n;

void insert(string &s, int idx) {
    int u = 0;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) ch[u][v] = ++tot;
        u = ch[u][v];
    }
    id[u] = idx;
}

void build() {
    queue<int> q;
    for (int i = 0; i < SIGMA; i++)
        if (ch[0][i]) q.push(ch[0][i]);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int i = 0; i < SIGMA; i++) {
            if (ch[u][i]) {
                fail[ch[u][i]] = ch[fail[u]][i];
                in[fail[ch[u][i]]]++;
                q.push(ch[u][i]);
            } else ch[u][i] = ch[fail[u]][i];
        }
    }
}

void query(string &t) {
    int u = 0;
    for (char c : t) {
        u = ch[u][c - 'a'];
        val[u]++;
    }
}

void topo() {
    queue<int> q;
    for (int i = 0; i <= tot; i++)
        if (in[i] == 0) q.push(i);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (id[u]) res[id[u]] = val[u];
        int v = fail[u];
        val[v] += val[u];
        if (--in[v] == 0) q.push(v);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    for (int i = 1; i <= n; i++) {
        string s; cin >> s;
        insert(s, i);
    }
    build();
    string t; cin >> t;
    query(t);
    topo();
    for (int i = 1; i <= n; i++) cout << res[i] << '\n';
    return 0;
}


七、进阶应用：AC 自动机上 DP
AC 自动机是 DFA，天然支持动态规划，典型问题：求长度为 \(m\)、不包含任何给定模式串的字符串数量。
核心思路

标记「危险状态」：自身是模式串结尾，或 fail 链上存在模式串结尾；

DP 状态：\(f\left[i\right][j]\) 表示长度为 \(i\)、当前在状态 \(j\) 的合法字符串方案数；

转移：枚举下一个字符，
